const char* gm_static_string(int32_t index) {
    return (index >= 0 && index < GM_STRING_TABLE_LEN)
        ? (const char*)GM_STRING_DATA + GM_STRING_ROWS[index].offset : NULL;
}

int gm_event_code(int32_t object, int32_t type, int32_t subtype) {
    for (int i = 0; i < GM_EVENT_COUNT; i++)
        if (GM_EVENTS[i].object == object && GM_EVENTS[i].type == type &&
            GM_EVENTS[i].subtype == subtype) return GM_EVENTS[i].code;
    return -1;
}

/* dispatch(): own event first, then the first ancestor carrying one. */
int gm_event_code_chain(int32_t object, int32_t type, int32_t subtype) {
    int c = gm_event_code(object, type, subtype);
    if (c >= 0) return c;
    int n = gm_object_parent_count(object);
    for (int k = 0; k < n; k++) {
        c = gm_event_code(gm_object_parent(object, k), type, subtype);
        if (c >= 0) return c;
    }
    return -1;
}

